import { NextResponse } from 'next/server';
import fs from 'fs';
import path from 'path';
import { db } from '@/server/db/database';

export const dynamic = 'force-dynamic';

export async function GET() {
  try {
    const graphData = db.getGraph();
    let edges = [...graphData.edges];

    // Load correlation edges generated by the Spark correlation job if present
    const corrPath = path.join(process.cwd(), 'data', 'correlation-graph.json');
    if (fs.existsSync(corrPath)) {
      try {
        const corrContent = fs.readFileSync(corrPath, 'utf8');
        const corrJson = JSON.parse(corrContent);
        if (corrJson && Array.isArray(corrJson.edges)) {
          const existingIds = new Set(edges.map(e => e.id));
          for (const edge of corrJson.edges) {
            if (!existingIds.has(edge.id)) {
              edges.push(edge);
              existingIds.add(edge.id);
            }
          }
        }
      } catch (e) {
        console.warn('Failed to parse correlation-graph.json:', e);
      }
    }

    return NextResponse.json({
      success: true,
      nodeCount: graphData.nodes.length,
      edgeCount: edges.length,
      data: {
        nodes: graphData.nodes,
        edges
      }
    });
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : String(err);
    return NextResponse.json({ success: false, error: message }, { status: 500 });
  }
}
